/* terry-pop.js v3 (Oct 15, 2026): grows in from 75% and shrinks back out over the 4 second dance.
   v2 (Oct 15, 2026): the little dance from the end of the animation, 4 seconds, 60% smaller.
   (first version Oct 14, 2026)
   Terry, the little TempleOS dancing figure, pops up when the Posture tile on
   Mini Habits is tapped to done. His background is see-through, so only the
   guy shows over the cue card board. He grows out of the tile you tapped,
   dances for a few seconds, then fades. He never blocks a tap underneath.
   The artwork is Terry's own sprite from the TempleOS web page, 100 frames,
   packed into this file so there is nothing else to load.
   Use: TerryPop.show(buttonElement) */
(function(){
  var ANIM='data:image/webp;base64,';
  var STILL='data:image/png;base64,';
  var W=128, H=176, SHOW_MS=4000, START=0.75, GROW=0.14, timer=null, cur=null;
  /* v3: he starts at 75% of his size, grows to full over the first 14% of the 4 seconds,
     dances, then shrinks the same 25% over the last 14% while fading out. Feet stay planted. */
  var reduce=false;
  try{ reduce=!!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches); }catch(e){}

  var css=document.createElement('style');
  css.textContent=
    '#terrypop{position:fixed;z-index:99999;pointer-events:none;margin:0;padding:0;transform-origin:50% 100%;'+
      'filter:drop-shadow(0 6px 10px rgba(0,0,0,.28))}'+
    '#terrypop img{display:block;width:100%;height:100%;background:transparent}';
  document.head.appendChild(css);

  function clear(){
    if(timer){ clearTimeout(timer); timer=null; }
    if(cur && cur.parentNode) cur.parentNode.removeChild(cur);
    cur=null;
  }
  function hide(){ clear(); }

  function show(anchor){
    clear();
    var vw=window.innerWidth||document.documentElement.clientWidth, vh=window.innerHeight||document.documentElement.clientHeight;
    var scale=0.8, w=Math.round(W*scale), h=Math.round(H*scale);   /* 60% smaller than the old 2x size (2 x 0.4 = 0.8) */
    var r=null; try{ r=anchor && anchor.getBoundingClientRect(); }catch(e){}
    var cy=r?r.top+r.height/2:vh/2;
    /* to the right of the tapped tile, vertically centred on it; on a narrow screen, centred */
    var left=r?r.right+14:(vw-w)/2;
    if(left+w>vw-8) left=Math.max(8,(vw-w)/2);
    var top=cy-h/2;
    top=Math.max(8,Math.min(vh-h-8,top));
    var el=document.createElement('div');
    el.id='terrypop'; el.setAttribute('aria-hidden','true');
    el.style.cssText='left:'+left+'px;top:'+top+'px;width:'+w+'px;height:'+h+'px';
    var img=new Image(); img.alt=''; img.draggable=false;
    img.src=reduce?STILL:ANIM;
    el.appendChild(img);
    document.body.appendChild(el);
    cur=el;
    timer=setTimeout(function(){ if(cur===el) clear(); }, SHOW_MS+300);
    if(el.animate){
      var s0='scale('+START+')', s1='scale(1)';
      var frames=reduce
        ? [{offset:0,opacity:0},{offset:GROW,opacity:1},{offset:1-GROW,opacity:1},{offset:1,opacity:0}]
        : [{offset:0,transform:s0,opacity:0,easing:'cubic-bezier(.2,.9,.3,1)'},
           {offset:GROW,transform:s1,opacity:1},
           {offset:1-GROW,transform:s1,opacity:1,easing:'ease-in'},
           {offset:1,transform:s0,opacity:0}];
      var a=el.animate(frames,{duration:SHOW_MS,fill:'both'});
      a.onfinish=function(){ if(cur===el) clear(); };
    }
  }
  window.TerryPop={show:show,hide:hide};
})();
